  ["north-tov-broken-accord-vulak"] = {overview = {"A seasonal North ToV side raid tuned for 24–36 level-60 characters, with up to three characters per player.", "Break six court oaths, then challenge Vulak's final judgment. Clear calls, fixed camps and assigned jobs give each three-character team time to respond."}, roles = {{id = "tank", label = "Tanks", tips = {"Use two tanks. In the opening, hold Vulak beside Dais Ember, away from Isolation Witness. During Banked Flame, hold him centrally outside both Embers; the marked tank hands off on Unworthy Guardian.", "Keep a tank on Vulak during both Concord wards. Move with the raid on the later IN and OUT calls."}}, {id = "healer", label = "Healers and curers", tips = {"Assign a poison curer and backup for the opening. Split healing between both Ember teams in the middle phase, and cover the echo tank during Concord.", "Recover everyone after each impact before the next deadline. Below 20%, faster reversals and increased melee leave less room to catch up."}}, {id = "damage", label = "Damage dealers", tips = {"Switch all damage to the two court echoes during Concord. Existing damage-over-time effects cannot bypass the ward.", "Keep two full three-character teams at each Ember for soaks, then move all teams together for IN and OUT. The isolated team must stay at most three characters."}}, {id = "everyone", label = "Everyone", tips = {"Assign jobs by three-character team where possible. Read the named target, camp and countdown; check every character rather than moving only your main.", "Start each deadline healthy. A 75%-maximum-HP failure leaves little room for existing damage or the dragon's next attack."}}}, phases = {{label = "Opening oaths", trigger = "100–70% health", description = "Alternate Reflection and Venom Ledger. Hold the boss beside Dais Ember so tank and melee remain with the main camp."}, {label = "First Concord", trigger = "70% health", description = "Finish any current assignment and recovery, then defeat two court echoes while a tank holds the protected boss. Reposition centrally outside both soak camps during the recovery after the ward breaks."}, {label = "Banked oaths", trigger = "70–35% health", description = "Alternate Banked Flame and Unworthy Guardian."}, {label = "Final Concord", trigger = "35% health", description = "Finish any current assignment and recovery, then defeat the second pair of court echoes while a tank holds Vulak."}, {label = "Winter's judgment", trigger = "35–20% health", description = "Alternate IN at Dais Ember and OUT at Arch Ember every 35 seconds, retaining ten-second warnings."}, {label = "The Last Oath", trigger = "20% health", description = "After the current assignment and recovery, reversals accelerate to every 30 seconds and melee rises 15%. There is no third echo wave."}}, abilities = {{name = "Fractured Reflection", summary = "The named non-tank has twelve seconds to reach the Isolation Witness. Move that character's three-character team together.", description = {"The named non-tank has twelve seconds to reach the Isolation Witness. Move that character's three-character team together.", "At impact, the marked character must be within the refuge's 15-unit radius, on its floor with clear line of sight. Only one to three living player characters may occupy the 25-unit-radius blast around the mark. A correct small group takes 900 damage each.", "Missing the refuge or crowding the blast deals 75% of maximum HP to the marked character and nearby living players. Keep the main raid with the boss, away from the refuge.", "Death, disconnecting or zoning does not cancel the assignment. The blast still resolves at the marked character's last position if the target is lost."}, tags = {}, roles = {"everyone"}}, {name = "Venom Ledger", summary = "Cure all eight poison counters from the named tank within twelve seconds. Clerics, druids and shamans can perform the assignment using Counteract Poison.", description = {"Cure all eight poison counters from the named tank within twelve seconds. Clerics, druids and shamans can perform the assignment using Counteract Poison.", "If any counters remain at expiry, the tank takes 75% of maximum HP and the rest of the raid takes 25%; the debuff then clears. Death, disconnecting or zoning also fails the assignment at its original deadline."}, tags = {}, roles = {"everyone"}}, {name = "Banked Flame", summary = "Fill both fixed braziers with at least six living player characters each before the twelve-second warning expires. Stand within each camp's 20-unit radius, on its floor with clear line of sight. Pets and dead characters do not count.", description = {"Fill both fixed braziers with at least six living player characters each before the twelve-second warning expires. Stand within each camp's 20-unit radius, on its floor with clear line of sight. Pets and dead characters do not count.", "Keep the main tank outside both camps and face the dragon away from them. Each successful camp divides 9,000 damage among its occupants when both camps are filled.", "Any missed camp causes one raidwide hit for 75% of maximum HP, replacing divided damage for that assignment. Each missed camp also adds 10% boss melee for thirty seconds."}, tags = {}, roles = {"everyone"}}, {name = "Unworthy Guardian", summary = "When the current tank is named, the second tank has twelve seconds to take over.", description = {"When the current tank is named, the second tank has twelve seconds to take over.", "If the marked tank still holds the dragon at impact, that character takes 75% of maximum HP and the rest of the raid takes 25%. The boss also gains 15% melee for thirty seconds.", "The marked tank receives one percentage hit, never both the primary and collateral damage. Keep healing through the brief recovery."}, tags = {}, roles = {"everyone"}}, {name = "Hoarfrost Reversal", summary = "Move to the announced fixed safe camp within ten seconds. IN and OUT alternate, starting with IN; follow the named landmark rather than estimating distance from the dragon.", description = {"Move to the announced fixed safe camp within ten seconds. IN and OUT alternate, starting with IN; follow the named landmark rather than estimating distance from the dragon.", "At impact, living players outside the announced camp's 20-unit radius take 75% of their maximum HP. Stand on the camp's floor with clear line of sight. The tank moves with the raid while the dragon anchors and stops summoning for the assignment."}, tags = {}, roles = {"everyone"}}, {name = "Concord", summary = "At 70% and 35% health, Vulak becomes protected and summons two court echoes. Switch all damage to the echoes; the ward blocks existing damage-over-time effects too. Vulak keeps attacking, so maintain a boss tank throughout.", description = {"At 70% and 35% health, Vulak becomes protected and summons two court echoes. Switch all damage to the echoes; the ward blocks existing damage-over-time effects too. Vulak keeps attacking, so maintain a boss tank throughout.", "Kill both within thirty seconds. A missed deadline causes one raidwide 75%-maximum-HP hit and increases Vulak's melee 10%, with another deadline every fifteen seconds while an echo survives.", "The Concord melee penalty caps at 30% and ends with the ward when both echoes die. Health holds at the transition threshold while the current assignment finishes, followed by eight seconds to recover before the next phase begins."}, tags = {}, roles = {"everyone"}}, {name = "Arbiter's pulse", summary = "Recurring raid damage between assignments.", description = {"A routine raid pulse is scheduled every 25 seconds. Assignment warnings, wards and recovery postpone it; missed pulses do not build into a burst."}, tags = {"raid damage"}, roles = {"healer", "everyone"}}}, sections = {{title = "Entry and raid preparation", paragraphs = {"This side raid requires active Season 1 characters of level 55 or higher, with both personal and server Velious access. Combat and equipment are designed around level 60."}, bullets = {"In the public Temple of Veeshan, the raid leader asks Echo of the First Brood for The Broken Accord with 12–36 eligible characters. Each member then says ready to enter to the Echo.", "Inside, the expedition leader says challenge to the selected Oath Witness. Fight the six courts in any order, one at a time; completing all six reveals Vulak. Challenge his Oath Witness when ready.", "The first challenge locks the raid's combat budget, with a 24-character minimum and a 36-character maximum. A 12-character request keeps the 24-character tuning floor and both six-character soak requirements. Later roster changes do not reduce that budget."}}, {title = "Positioning and warnings", paragraphs = {}, bullets = {"Opening main camp and later IN camp: Dais Ember. OUT camp: Arch Ember. Both have a 20-unit radius. Isolation Witness has a 15-unit refuge radius and a 25-unit blast around the marked character.", "Banked Flame requires six living characters at Dais Ember and six at Arch Ember. The boss tank stays outside both; use the Concord recovery to reposition.", "Use the named stationary landmarks on their flat floor, with clear line of sight. A matching camp icon confirms that a character counts as inside. Circles are an extra cue; follow chat calls and countdowns even when terrain makes them hard to see."}}, {title = "Timing and damage pressure", paragraphs = {}, bullets = {"Assignments normally begin every 35 seconds, alternating the mechanics of the current phase. Below 20%, reversals shorten to every 30 seconds; their warning remains ten seconds.", "After an assignment resolves, there is an eight-second recovery before another scripted assignment or routine pulse. Boss melee generally continues. A failure dealing 75% to the current tank briefly pauses boss melee for two seconds.", "Percentage failures remove the stated share of maximum HP and bypass mitigation and absorption. They can kill an injured character; no one-HP survival floor applies. Recover before the next call.", "Soft enrage begins at twelve minutes, adding 10% melee and another 10% every 30 seconds. Combined scripted melee increases cap at 50%."}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the active fight after ten seconds without living engaged members in the arena. Completed courts and cleared trash remain saved; a failed attempt does not reopen defeated courts.", "Keep the dragon in its court. A six-second leash warning gives the raid time to return before the attempt resets.", "The expedition lasts eight hours and has a separate 48-hour replay timer. Saved return, when enabled, keeps the original clocks."}}, {title = "Evolving rewards", paragraphs = {"The separate evolving pool drops only form I. Each line has six total forms, starting near 60% of its final base-stat budget and ending around the static raid equipment's power."}, bullets = {"Form I is level 60, Lore and Kinbound, shareable within the same forum before equip. Equipping binds it to that character. Forms II–VI are standard NO TRADE and remain with that character.", "Equip and activate the item to progress. Five upgrades require 300, 600, 900, 1,200 and 1,500 additional qualifying kills, totaling 4,500. Experience-eligible level-50+ kills in any zone count, including for fully level/AA-capped characters. Gray kills and scripted raid adds do not count; evolution XP transfer is unavailable.", "Caster shield, secondary: NEC, WIZ, MAG, ENC. Mana-preservation focus grows with the forms; a resistance click unlocks at form V.", "Bow, ranged: WAR, RNG, ROG. Its final form has 35 damage, 34 delay and range 200; its fire proc unlocks at form V.", "Chain wrist: RNG, ROG, SHM, BER. A vision click unlocks at form V.", "Leather arms: DRU, MNK, BST. A regeneration click unlocks at form V.", "Plate helm: WAR, CLR, PAL, SHD, BRD. A cold-resistance click unlocks at form V.", "Cloth hands: NEC, WIZ, MAG, ENC. The spell-haste focus improves through all six forms.", "Each line shares a Lore group across its forms. Multiple eligible equipped and activated lines can progress independently on the same qualifying kill."}}}},
  ["templeveeshan-vulak-aerr-ring-event"] = {overview = {"Survive the long Vulak ring through successive waves, split enemies and the final dragon."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep sustained add control and remain in the arena throughout the ring."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The controller starts its first stage one minute after activation and continues a timed multiwave sequence.", "Several enemies split on death, and selected wave bosses trigger nearby player recovery.", "Player deaths can create carrion enemies during the active portions of the event.", "The final stage summons Vulak. The controller checks for non-feigned players in the arena and cleans up if the area is abandoned."}}}},
  ["tenebrous-disciple-of-focus"] = {overview = {"Challenge the Disciple of Focus during the monk epic sequence."}, roles = {{id = "everyone", label = "Everyone", tips = {"Complete the dialogue with the eligible monk and have the party prepared before the challenge."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"An eligible monk at the relevant second-epic stage can hail the disciple and say 'challenge'.", "The challenge advances the initial eligible stage, removes the disciple's protection and starts combat.", "Leaving combat stops all quest timers."}}}},
  ["tenebrous-hoober"] = {overview = {"Subdue Hoober so he can safely receive the quest elixir."}, roles = {{id = "everyone", label = "Everyone", tips = {"Stop attacks at the surrender and have the quest turn-in ready."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Reduce Hoober to 20% health. He becomes invulnerable, falls down and clears his hate list.", "That creates a five-minute window to give the required elixir.", "Giving it before he is subdued returns the item and provokes him instead."}}}},
  ["tenebrous-johanius-barleou"] = {overview = {"Clear the hostile camp to progress Johanius's family rescue."}, roles = {{id = "everyone", label = "Everyone", tips = {"Defeat the camp's enemies rather than dragging them outside the area."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Loading the rescue encounter creates Aellana Barleou and Lyrra Rutledge.", "The controller watches the designated enemy types whose original spawn points belong to the camp.", "Once none remain, it signals Johanius to continue. Pulling them away does not count as clearing the camp."}}}},
  ["thenest-a-failed-expedition-shargone"] = {overview = {"Investigate the lost expedition and awaken Shargone after clearing enough enemies."}, roles = {{id = "everyone", label = "Everyone", tips = {"Speak to the survivor and stabilize the group before reaching twenty kills."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The twentieth non-pet kill in the zone summons Shargone once.", "Kallendro offers a protective fireskin effect when hailed; the expedition corpses provide clues.", "Prepare for the boss before the final qualifying kill."}}}},
  ["thenest-circle-of-drakes"] = {overview = {"Defend the ritual circle against five advancing waves of drakes."}, roles = {{id = "everyone", label = "Everyone", tips = {"Intercept drakes early and be ready to reacquire them after their protected march."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Three clients in the circle start the event, unless a GM bypasses that requirement.", "Five timed waves contain two, four, four, five and five drakes, with increasingly strong templates.", "Engaged drakes resume their march after a 30-second combat interval and briefly resist new aggression.", "Sixteen drake kills trigger the scripted objective update and focus spawn."}}}},
  ["thenest-in-the-shadows-vishimtar"] = {overview = {"Control eggs, corrupted drakes and curses while breaking Vishimtar's final health lock."}, roles = {{id = "everyone", label = "Everyone", tips = {"Reserve spirit interactions for cursed players.", "Assign egg damage and deliberate shadow control before the final curse cycle."}}}, phases = {{label = "Eggs and shadows", trigger = "99% through 51%", description = "Control eggs and new shadow spawns while keeping the tank healthy."}, {label = "Doom cycle", trigger = "26% health", description = "Use cursed players and mournful spirits to lower the health lock until the boss can die."}}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Eggs arrive on a repeating timer and hatch into six drakes if left for a minute.", "At 76% health, incorporeal shadows begin spawning. Killing one creates a lifedrain shadow and increases that new shadow's melee strength.", "At 51%, the fight adds another cloud and activates the corrupted drakes.", "At 26%, Vishimtar applies doom curses and becomes locked at 25% health. Cursed players must tell a mournful spirit 'shoulder my burden' to remove their curse and lower the lock by one point.", "An uncursed player can consume a spirit without lowering the lock. Two minutes out of combat resets the encounter."}}}},
  ["thenest-rampaging-monolith"] = {overview = {"Break the Rampaging Monolith into progressively smaller pieces while controlling its fragments."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign an add tank and clear fragments before pushing the next health threshold."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"At 85%, 70%, 55%, 40%, 25% and 10% health, the boss releases four debris and rubble adds.", "Each threshold also shrinks the boss, but does not remove the existing fragments.", "Pause boss damage when necessary to prevent several fragment waves overlapping."}}}},
  ["thenest-rivals"] = {overview = {"Navigate rival adventurers and decide how to handle the wounded Silverclaw."}, roles = {{id = "everyone", label = "Everyone", tips = {"Decide on the intended faction objective before promising to help Silverclaw."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The assigned task selects the Norrath's Keepers or Dark Reign rival party.", "Moving through the meeting area advances the negotiation and starts attacks from the local goblins and spiders.", "Silverclaw begins at half health. Promising not to harm him makes him protected and opens the recovery dialogue.", "Returning the stolen tooth spawns a chest and ends the expedition, but explicitly fails the assigned task and suppresses normal completion rewards for players inside."}}}},
  ["thenest-t-shara"] = {overview = {"Defeat T`Shara's aspects to remove her linked offensive and defensive benefits."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prioritize the protection aspect and coordinate damage during the time its benefit is absent."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The five aspects govern armor, combat, magic, power and protection; engaging the group links their aggression.", "Defeating an aspect removes its corresponding benefit but starts a 150-second respawn window.", "The aspects strengthen after thirty seconds of combat.", "If every aspect is dead at once, the protection aspect is immediately replaced, so plan the kill sequence deliberately."}}}},
  ["thenest-the-curse-of-jurek"] = {overview = {"Control the harsh winds thrown off by Ju`Rek as the fight progresses."}, roles = {{id = "everyone", label = "Everyone", tips = {"Have add control ready before every health threshold."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"At 95%, 80%, 60%, 40% and 20% health, Ju`Rek summons three harsh winds at his position.", "The winds remain until defeated or the encounter resets.", "Two minutes out of combat restores Ju`Rek and clears the wind adds."}}}},
  ["thenest-web-of-lies"] = {overview = {"Use careful diplomacy to choose a peaceful or hostile resolution with the nest's rivals."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep weapons unequipped during the negotiation and let one player lead the dialogue."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Approach the meeting with weapons put away; visible weapons or excessive delay can provoke the guards.", "Follow the future and other-reason dialogue toward surrender for the peaceful route.", "Choosing the kill response starts combat instead.", "The rival spokesperson depends on the assigned faction task."}}}},
  ["gukg-leklos-the-bonekeeper"] = {overview = {"Leklos guards the first stretch of the Accursed Sanctuary and changes into a skeletal form as his health falls."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 25% health, Leklos transforms from his normal form into a skeleton. Keep the same tank established through the change.", "Fight inside his area. Pulling him across the scripted boundary returns him home and clears his hate list.", "Defeating Leklos advances the rescue through the sanctuary; follow the allied NPCs’ directions to the next encounter."}}}},
  ["gukg-the-cursed-keeper"] = {overview = {"Finish the rescue by defeating the Cursed Keeper after Gragna falls."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 50% health, the Keeper replaces area rampage with rampage. At 20%, the remaining rampage ability is removed.", "Keep the boss in the rear encounter area. Crossing its leash boundary returns it home and clears combat.", "Healing back above the phase boundaries restores the earlier special-attack state. Maintain steady pressure through the final stages."}}}},
  ["gukg-the-cursed-spore"] = {overview = {"Help the Prophets of Gukta weaken the Cursed Spore while your raid drives its health down."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The Spore begins immune to slow. At 90% health, the prophets remove that immunity, creating an opportunity to slow its attacks.", "At 75%, 50% and 25% health, its elemental and magical resistances fall in stages. Casters should expect greater resistance early in the fight.", "Regaining health can restore earlier resistance stages. Leaving combat restores the initial resistances and slow immunity.", "Its defeat opens the route toward Gragna and the final Keeper encounter."}}}},
  ["akheva-time-corrupted-insanity-crawler"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "Follow the expedition compass to the broad chamber with the three named keystones. Keep the Crawler in that chamber while the Quarry uses the called keystone.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the Crawler at its arena origin, away from the three bait footprints.", "Pick up at most three Larvae; the tank is excluded from Quarry when another living eligible client exists."}}, {id = "healer", label = "Healers", tips = {"Prepare the Quarry for its predictable 20%-HP successful strike.", "Heal recovery windows before the next bait; no borrowed charm or unexplained Kerafyrm effect."}}, {id = "damage", label = "Damage dealers", tips = {"Find the final fissure in the three-message trail and kill its single Cyst.", "Clear bounded Larvae; normal damage schools remain useful below 20%."}}, {id = "everyone", label = "Everyone", tips = {"The Quarry moves into the named keystone while others stay outside 25 units.", "Read trail messages; only one Cyst becomes attackable, so a false landmark is not a hidden kill trap."}}}, phases = {{label = "Tremor Trail", trigger = "First at 18 seconds, then 32 seconds after each completed resolution.", description = "Name one non-tank Quarry and announce one of three fixed keystones (Bone, Obsidian or Eye). The Quarry has 12 seconds to enter the called 20-unit keystone area. Everyone else must be outside its fixed 25-unit impact area. The footprint is frozen at warning creation and does not follow the Quarry. Suspend summoning during the warning and recovery."}, {label = "Burrow and Breach", trigger = "At 75% and 45% HP, once each per pull; queue after any Tremor Trail.", description = "The boss burrows and becomes fully immune, including existing DoT ticks, for at most 20 seconds. Three protected surface-fissure landmarks remain stationary. Over the first 6 seconds, emit three clear trail messages that end at the actual exit; at 6 seconds only that exit exposes an attackable Resonant Cyst. The raid has 14 seconds to kill the single Cyst. The boss surfaces at its arena origin."}, {label = "Carrion Brood", trigger = "On an eligible player death during the fight, and specified failed bait/burrow checks.", description = "Each player death creates one Larva, with at most three living Larvae. Pet deaths create none. Each Larva has a twenty-second lifetime; its deadline pauses during a Tremor Trail warning."}, {label = "Psychic Reverberation / Exposed Nerve", trigger = "Routine pulse first at 12 seconds, then every 26 seconds; one announced transition at 20% HP.", description = "A 250-base-damage normal resistible magic pulse affects encounter participants within 125 units and pauses during assignments plus recovery. At 20%, the Crawler announces its final denial and retains the learned bait cycle."}}, abilities = {{name = "Tremor Trail", summary = "First at 18 seconds, then 32 seconds after each completed resolution.", description = {"Name one non-tank Quarry and announce one of three fixed keystones (Bone, Obsidian or Eye). The Quarry has 12 seconds to enter the called 20-unit keystone area. Everyone else must be outside its fixed 25-unit impact area. The footprint is frozen at warning creation and does not follow the Quarry. Suspend summoning during the warning and recovery.", "Success: If the Quarry is correctly positioned, the strike breaks the keystone and deals one 20%-maximum-HP hit to the Quarry. Other characters outside the 25-unit footprint take no hit. The boss's melee pauses 3 seconds; the keystone reforms only after the 8-second recovery.", "Failure: A Quarry outside the called area is dealt a 35%-maximum-HP hit and creates one Carrion Larva, subject to the cap. Other living characters inside the frozen 25-unit impact footprint receive one 35%-maximum-HP hit whether or not the bait succeeded. Death, disconnect or disappearance of the Quarry does not cancel or retarget the mark: resolve the original footprint and failed-bait Larva at the original 12-second deadline."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Burrow and Breach", summary = "At 75% and 45% HP, once each per pull; queue after any Tremor Trail.", description = {"The boss burrows and becomes fully immune, including existing DoT ticks, for at most 20 seconds. Three protected surface-fissure landmarks remain stationary. Over the first 6 seconds, emit three clear trail messages that end at the actual exit; at 6 seconds only that exit exposes an attackable Resonant Cyst. The raid has 14 seconds to kill the single Cyst. The boss surfaces at its arena origin.", "Success: Kill the Cyst by the 20-second total deadline. The Crawler resurfaces and has an 8-second melee/spell stagger while its exposed nerve retracts. Its ward releases immediately, so every damage class can attack normally.", "Failure: At 20 seconds the boss resurfaces, its ward always releases, and encounter participants take one 35%-maximum-HP hit. Create at most two Larvae, respecting the total-three cap. No full-health death sentence or endless immunity."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Carrion Brood", summary = "On an eligible player death during the fight, and specified failed bait/burrow checks.", description = {"Each player death creates one Larva, with at most three living Larvae. Pet deaths create none. Each Larva has a twenty-second lifetime; its deadline pauses during a Tremor Trail warning.", "Success: Kill the bounded adds, or control them briefly and then finish them before their deadline.", "Failure: A surviving Larva consumes itself at its deadline for one 20%-maximum-HP hit on its current target, then depops. No growth chain, corpse-spawn recursion or unbounded replacement adds."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Psychic Reverberation / Exposed Nerve", summary = "Routine pulse first at 12 seconds, then every 26 seconds; one announced transition at 20% HP.", description = {"A 250-base-damage normal resistible magic pulse affects encounter participants within 125 units and pauses during assignments plus recovery. At 20%, the Crawler announces its final denial and retains the learned bait cycle.", "Success: Normal mitigation controls routine damage; keep executing the same 12-second bait warnings through the finish.", "Failure: Normal pulse damage and the previously defined bait/add failures only."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"An eligible seasonal group or raid leader requests this expedition from Theta Sigma in the public encounter zone. The accepted roster may contain three to seventy-two characters with current personal and server Luclin access."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the same seasonal expedition through Theta Sigma. The existing three-day instance and two-day replay deadlines continue. Saved return is available only when that expedition has been registered successfully."}}}},
  ["arena2-heigan-the-unclean-the-safety-dance"] = {overview = {"Follow the safe floor wedges while managing fever and mana burn."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"During combat, cure Decrepit Fever with disease cures.", "Pure casters should leave the purple mana-burn radius and use the refuge when warned.", "During the dance, follow the safe wedge as it travels across the floor and back. Warnings shorten on later dances.", "Combat lasts 90 seconds and each dance lasts 45 seconds."}}}},
  ["arena2-living-legacy-battle-prowess"] = {overview = {"Defeat the Avatar quickly while matching each defense and destroying despair adds."}, roles = {}, phases = {{label = "Open defenses", trigger = "100% to 75%", description = "Every spell and weapon is effective."}, {label = "Changing defenses", trigger = "75% to 25%", description = "In order: cold and hand-to-hand; magic and piercing; poison and slashing; disease and blunt; fire and two-handed weapons."}, {label = "Final assault", trigger = "Below 25%", description = "All attack types become effective again."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Match the announced spell school or weapon style as the Avatar changes defenses.", "Stand inside a green rune for two seconds to gain twenty seconds of attunement when your usual attacks are unsuitable.", "Destroy each trio of despair manifestations within 45 seconds.", "The final quarter of the Avatar's health opens every attack type again."}}}},
  ["arena2-trial-of-the-dreadscale-difficult"] = {overview = {"A cooperative movement trial with four health locks and difficult difficulty."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Bring at least three players and respond to the floor markers together.", "This difficulty gives 4.5 seconds for ordinary hazard warnings.", "At 80%, occupy all three seals and hold them for 4 seconds.", "At 60%, dodge the sweeping fields, then gather three players in the blue rally circle.", "At 40%, divide the group between the two violet circles and keep both sides balanced.", "At 20%, survive the final patterns. A failed trial causes a short empowered attack window before the trial repeats."}}}},
  ["arena2-trial-of-the-dreadscale-insane"] = {overview = {"A cooperative movement trial with four health locks and insane difficulty."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Bring at least three players and respond to the floor markers together.", "This difficulty gives 3.5 seconds for ordinary hazard warnings.", "At 80%, occupy all three seals and hold them for 4.5 seconds.", "At 60%, dodge the sweeping fields, then gather three players in the blue rally circle.", "At 40%, divide the group between the two violet circles and keep both sides balanced.", "At 20%, survive the final patterns. A failed trial causes a short empowered attack window before the trial repeats."}}}},
  ["arena2-trial-of-the-dreadscale-moderate"] = {overview = {"A cooperative movement trial with four health locks and moderate difficulty."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Bring at least three players and respond to the floor markers together.", "This difficulty gives 5.5 seconds for ordinary hazard warnings.", "At 80%, occupy all three seals and hold them for 3.5 seconds.", "At 60%, dodge the sweeping fields, then gather three players in the blue rally circle.", "At 40%, divide the group between the two violet circles and keep both sides balanced.", "At 20%, survive the final patterns. A failed trial causes a short empowered attack window before the trial repeats."}}}},
  ["arena2-trial-of-the-dreadscale-simple"] = {overview = {"A cooperative movement trial with four health locks and simple difficulty."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Bring at least three players and respond to the floor markers together.", "This difficulty gives 6.5 seconds for ordinary hazard warnings.", "At 80%, occupy all three seals and hold them for 3 seconds.", "At 60%, dodge the sweeping fields, then gather three players in the blue rally circle.", "At 40%, divide the group between the two violet circles and keep both sides balanced.", "At 20%, survive the final patterns. A failed trial causes a short empowered attack window before the trial repeats."}}}},
  ["stillmoonb-death-comes-swiftly-lair-mistress"] = {overview = {"Defeat the crawling warders to expose the Lair Mistress."}, roles = {{id = "everyone", label = "Everyone", tips = {"Regroup before the fifth warder dies."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The controller counts the designated crawling warder deaths.", "The fifth qualifying death spawns the Lair Mistress.", "Finish the newly revealed named encounter to advance the mission objective."}}}},
  ["stillmoonb-drake-eggs"] = {overview = {"Recover the drake eggs and investigate the ambush around the dead contact."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare to handle the guard and statues when the egg-carrying drake falls."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The mission marks one specific drake spawn group as the egg carrier.", "Killing that drake creates a goblin guard, two guardian statues and the dead contact.", "The trigger is tied to the designated spawn group, so killing an arbitrary drake does not start it."}}}},
  ["stillmoonb-kessdona-s-perch"] = {overview = {"Exhaust Kessdona's manashards, then identify the correct protector at each health lock."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign someone to identify the true protector and avoid indiscriminate area damage on protector groups."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"While manashards remain active, reaching 90% heals Kessdona and drains their resources. Defeat the depleted guardians to progress.", "At 80%, 60%, 40% and 20%, protectors hold her health in place.", "Find and defeat the true focus among each protector group. Killing a wrong protector restores health and restarts that stage.", "She also uses a charm timer; leaving combat triggers failure cleanup after 30 seconds."}}}},
  ["stillmoonb-rikkukin-the-defender"] = {overview = {"Respond to Rikkukin's directional warnings and wait out his frozen-aura stages."}, roles = {{id = "everyone", label = "Everyone", tips = {"Move away from the announced attack side and conserve damage resources during Frozen Aura."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"His warning identifies a right-claw, left-claw, tail or frontal breath attack before the cast follows.", "At 65% and 30%, Frozen Aura begins a 30-second health-lock window; trying to push past its lower threshold heals him back.", "After the first frozen stage, periodic light-reflection warnings lead to a blind effect.", "Thirty seconds out of combat resets the fight."}}}},
  ["stillmoonb-storm-dragon-scales-the-storm-caller"] = {overview = {"Uncover the Storm Caller by advancing the climb and entering the gust of wind."}, roles = {{id = "everyone", label = "Everyone", tips = {"Consolidate the group before approaching the new gust."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Thirty qualifying deaths reveal the gust trigger.", "Entering its proximity spawns the Storm Caller and four Ascent storms at their fixed locations.", "Prepare for both the caller and the nearby storm enemies before advancing the trigger."}}}},
  ["stillmoonb-sudden-tremors-ancient-golem"] = {overview = {"Open the runed chest before defeating the Ancient Golem to preserve the mission sequence."}, roles = {{id = "everyone", label = "Everyone", tips = {"Handle the chest before committing damage to the golem."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Destroying or opening the scripted runed chest marks the chest objective as complete.", "Once that flag is set, the living golem emits an earthquake warning and camera tremor on its one-minute timer.", "The source warns that killing the golem before opening the chest can leave the mission incomplete."}}}},
  ["mmcc-struggles-within-the-progeny-valdoon-kel-novar"] = {overview = {"Weaken Valdoon through his guardians, expose the false lord and survive the true vampire’s shifting attacks."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Each Guardian of Kel’Novar killed removes 30,000 health from the true Valdoon. Clear the guardians before engaging him.", "Defeating the false Valdoon creates another guardian and enables an additional final reward container in the raid version.", "The true Valdoon can call three to five lookouts, drain the raid’s vitality and briefly increase his melee damage. Collect lookouts quickly and reinforce the tank when his muscles-bulge emote appears.", "Seneschal’s Petrification repeats during combat. Keep backup tank control available when the top-hate target is affected.", "Stay inside the aviary. Leaving combat for ninety seconds heals Valdoon and clears the lookouts."}}}},
  ["bloodfields-discordling-dark-animist"] = {overview = {"A beastlord epic encounter opens with six savage ferans."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Assemble before the boss appears; its appearance lasts thirty minutes.", "Assign control for the six ferans immediately on spawn.", "Keep the boss tank covered while the group reduces the add pressure."}}}},
  ["bloodfields-elite-dragorn-jekisia"] = {overview = {"Chase Jekisia through the caverns while handling her repeated reinforcements."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"At successive health thresholds, Jekisia relocates and calls pairs of dragorn flunkies.", "Clear or control the flunkies before the group follows her to the next position.", "Keep moving through the stages; the encounter has a twenty-minute reset timer.", "Remaining flunkies are not automatically removed by the boss's death."}}}},
  ["bloodfields-gazz-the-gargantuan"] = {overview = {"Wake Gazz by defeating the dreamwalkers, then adapt to his alternating combat modes."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Defeat the three dreamwalkers and prepare for Gazz to awaken.", "When Gazz slows and flails, keep vulnerable players clear of the area-rampage pressure.", "His later roar leads into Reflective Sheen; watch the change before committing spells.", "A prolonged disengagement starts the event reset sequence."}}}},
  ["bloodfields-kragsmash"] = {overview = {"Kragsmash calls strength and speed adds at three health thresholds."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The eligible monk starts the challenge through dialogue.", "At 75%, 50% and 25%, collect the paired strength and speed adds.", "Keep enough damage and healing available to finish inside the thirty-minute combat window."}}}},
  ["bloodfields-marshal-histent-grinbik-the-fertile-rescue"] = {overview = {"Defeat Marshal Histent and subdue Grinbik to free him from control."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Handle the marshal and his supporting enemies without losing control of Grinbik.", "Lower Grinbik to 10% and allow the surrender check to complete.", "The eligible ranger should hail the freed Grinbik to finish the rescue."}}}},
  ["bloodfields-reclusive-girplan-chain-rolthee-and-myrhee"] = {overview = {"A chain of reclusive girplans leads to a quest-dependent named opponent."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Defeat each emerging girplan to bring out the next one.", "Tanks should regain threat after the recurring knockback and hate wipe.", "Each stage has a 930-second appearance timer; keep the chain moving.", "The final branch produces Rolthee or Myrhee according to quest state."}}}},
  ["bloodfields-the-keeper"] = {overview = {"The Keeper accepts a monk's epic challenge for a limited time."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The eligible monk must start the challenge through dialogue.", "Defeat the Keeper within the thirty-minute combat window.", "Maintain steady tanking and healing through his health-based taunts."}}}},
  ["bloodfields-war-caller-kaavi"] = {overview = {"Clear Kaavi's defenders before confronting the war caller."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Defeat the sentries and guardians that prevent Kaavi from being attacked.", "Keep add control available when the boss becomes vulnerable.", "At 90% health, Kaavi's NPC script summons two additional sentinels."}}}},
  ["soldungc-culthor-the-gatekeeper"] = {overview = {"Culthor grows more dangerous as his linked guards are removed."}, roles = {{id = "everyone", label = "Everyone", tips = {"Choose the guard kill order deliberately and prepare tank cooldowns for the final guards."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The Firewatcher starts the encounter for a rogue at the required epic step after the four-part turn-in.", "Culthor links to his guards when combat begins.", "His maximum melee damage increases as the guard count falls from six to zero."}}}},
  ["soldungc-fireback-queen"] = {overview = {"Survive successive fireback waves until the queen becomes the final target."}, roles = {{id = "everyone", label = "Everyone", tips = {"Control the arriving spiderlings and regroup before advancing the next stage."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The controller begins with an untargetable queen and a proximity trigger.", "Spiderling deaths advance the counter through several replacement queen stages and additional waves.", "The final counter threshold replaces the last protected stage with the attackable Fireback Queen."}}}},
  ["soldungc-protector-of-fire-pure-flame-elemental"] = {overview = {"Clear the elemental ring to summon its final fire guardian."}, roles = {{id = "everyone", label = "Everyone", tips = {"Finish each wave and prepare for the two possible finale variants."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Eight initial kill signals summon four furious magma guardians.", "Defeat those four to summon two inflamed champions.", "After both champions die, the final spawn is Protector of Fire or the epic-specific Pure Flame Elemental, depending on the qualifying wizard signal."}}}},
  ["thedeep-deklean-korgad-invisible-bridge"] = {overview = {"Earn Deklean's help and follow his marked route across the invisible bridge."}, roles = {{id = "everyone", label = "Everyone", tips = {"Follow the guide and beacons carefully instead of using the visible false bridge."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Complete Deklean's requested proof and supplies turn-in to begin the bridge route.", "As he advances, he places beacons along the safe crossing.", "After the route ends he starts a short despawn timer; combat changes his cleanup timing."}}}},
  ["thedeep-the-burrower-beast"] = {overview = {"Enter the Burrower Beast's chamber to begin a prolonged sequence of burrowers and parasites."}, roles = {{id = "everyone", label = "Everyone", tips = {"Plan for a long defense and keep at least one active player in the arena."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Entering the trigger area spawns a massive burrower and starts the first wave after 45 seconds.", "The next wave ticks are five minutes apart: early waves contain twelve mixed burrowers, followed by six core burrowers and then parasite larvae.", "A skipped wave creates a ten-minute gap before the final burrower parasite.", "The controller resets when no non-feigned player remains in the encounter area."}}}},
}
